for a in articles: ensure_url(f'{BASE}/blog/{a["slug"]}/','0.7',BASE+a['image'],a['title'],a['image_alt'])
tree.write(sm,encoding='utf-8',xml_declaration=True)
state={'date':DATE,'timezone':'Asia/Shanghai','status':'generated_pending_validation','article_quota':2,'articles':[{'slug':a['slug'],'title':a['title'],'url':f'{BASE}/blog/{a["slug"]}/','primary_keywords':a['keywords'],'keyword_source':a['keyword_source'],'intent_cluster':a['intent_cluster']} for a in articles],'index_updated':True,'sitemap_updated':True,'generated_at':datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=8))).isoformat(),'image_generation':{'status':'pass','model':'opus-image-1.5 via configured custom Sub2API Responses API /v1/responses with image_generation tool','generated_at':datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=8))).isoformat(),'files':[r['file'] for r in image_results],'results':image_results}}
(ROOT/'output/daily_blog_automation_state.json').write_text(json.dumps(state,indent=2),encoding='utf-8')
print('generated', [a['slug'] for a in articles], 'blog_count', count, 'images', [r['file'] for r in image_results])
